def has_close_elements(numbers: list, threshold: float = 1.0) -> bool:
    if len(numbers) < 2 or threshold <= 0:
        return False

    sorted_numbers = sorted(numbers)
    return any(
        abs(sorted_numbers[i] - sorted_numbers[i - 1]) < threshold
        for i in range(1, len(sorted_numbers))
    )

def separate_paren_groups(paren_string: str) -> list:
    groups = []
    current = []
    depth = 0

    for char in paren_string:
        if char.isspace():
            continue

        current.append(char)

        if char == "(":
            depth += 1
        elif char == ")":
            depth -= 1
            if depth == 0:
                groups.append("".join(current))
                current = []

    if current:
        groups.append("".join(current))

    return groups

def below_zero(operations: list) -> bool:
    balance = 0
    for operation in operations:
        balance += operation
        if balance < 0:
            return True
    return False

def mean_absolute_deviation(numbers: list) -> float:
    if not numbers:
        raise ValueError("numbers must not be empty")

    mean = sum(numbers) / len(numbers)
    return sum(abs(number - mean) for number in numbers) / len(numbers)

def intersperse(numbers: list, delimiter: int) -> list:
    result = []
    for i, number in enumerate(numbers):
        if i > 0:
            result.append(delimiter)
        result.append(number)
    return result

def parse_nested_parens(paren_string: str) -> list:
    nesting_levels = []

    for group in paren_string.split():
        depth = 0
        max_depth = 0

        for char in group:
            if char == "(":
                depth += 1
                max_depth = max(max_depth, depth)
            elif char == ")":
                depth -= 1

        nesting_levels.append(max_depth)

    return nesting_levels
